def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    pairs = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == col:
                    pairs.append((r, c, dr, dc, col))
    # Extend each same-color diagonal pair across background cells only.
    for r, c, dr, dc, col in pairs:
        for sign in (-1, 1):
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] in (bg, col):
                if grid[rr][cc] == bg:
                    out[rr][cc] = col
                rr += sign * dr
                cc += sign * dc
    return out

