                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    for sign in (-1, 1):
                        y, x = r, c
                        while 0 <= y < h and 0 <= x < w and grid[y][x] in (bg, color):
                            if grid[y][x] == bg:
                                out[y][x] = color
                            y += sign * dr
                            x += sign * dc
    return out
